{
  "action_updates": [
    {
      "action_id": "A10",
      "preconditions": [
        {
          "requirement_id": "A10_pre_1",
          "condition": "The gauze roll is wrapped around the burn area.",
          "source": "graph_dependency",
          "source_reference": "A10 depends on A9",
          "requires_expert_review": false,
          "evidence_specification": {
            "evidence_types": [
              "rgb_frame",
              "object_identity"
            ],
            "relevant_entities": [
              "gauze",
              "burn"
            ],
            "observable_cues": [
              "gauze covering or encircling the burn site"
            ],
            "temporal_scope": "before_action",
            "verification_method": "VLM",
            "observability": "visually_observable",
            "current_support": "partial",
            "limitations": [
              "only after_step snapshots are provided; the state before A10 is inferred from A9's completion"
            ]
          }
        }
      ],
      "postconditions": [
        {
          "requirement_id": "A10_post_1",
          "condition": "The gauze is secured in place by medical tape.",
          "source": "explicit_instruction",
          "source_reference": "Secure the gauze with medical tape",
          "requires_expert_review": false,
          "evidence_specification": {
            "evidence_types": [
              "rgb_frame",
              "object_identity",
              "spatial_position"
            ],
            "relevant_entities": [
              "medical tape",
              "gauze"
            ],
            "observable_cues": [
              "medical tape adhered to the gauze and surrounding non-burned skin"
            ],
            "temporal_scope": "after_action",
            "verification_method": "VLM",
            "observability": "visually_observable",
            "current_support": "supported",
            "limitations": [
              "occlusion of tape edges may prevent confirming full security"
            ]
          }
        },
        {
          "requirement_id": "A10_post_2",
          "condition": "The medical tape is not in contact with the burned skin.",
          "source": "explicit_instruction",
          "source_reference": "keeping the tape off the burned skin",
          "requires_expert_review": false,
          "evidence_specification": {
            "evidence_types": [
              "rgb_frame",
              "object_identity",
              "spatial_position"
            ],
            "relevant_entities": [
              "medical tape",
              "burned skin"
            ],
            "observable_cues": [
              "spatial separation between tape edges and visible burned area"
            ],
            "temporal_scope": "after_action",
            "verification_method": "VLM",
            "observability": "partially_observable",
            "current_support": "partial",
            "limitations": [
              "gauze and tape may fully occlude the burned skin, making contact impossible to rule out from RGB alone"
            ]
          }
        }
      ],
      "error_criteria": [
        {
          "criterion_id": "A10_E1",
          "error_type": "spatial_error",
          "violation_condition": "Medical tape is adhered directly to the burned skin.",
          "compliance_condition": "Medical tape is adhered only to the gauze and healthy skin.",
          "applicability_condition": "Medical tape is being applied to secure the dressing.",
          "related_requirement_ids": [
            "A10_post_2"
          ],
          "source": "explicit_instruction",
          "source_reference": "keeping the tape off the burned skin",
          "requires_expert_review": false,
          "evidence_specification": {
            "evidence_types": [
              "rgb_frame"
            ],
            "relevant_entities": [
              "medical tape",
              "burned skin"
            ],
            "observable_cues": [
              "visual overlap of tape and burned skin texture"
            ],
            "temporal_scope": "after_action",
            "verification_method": "VLM",
            "observability": "partially_observable",
            "current_support": "partial",
            "limitations": [
              "occlusion of the burn by gauze makes definitive contact detection difficult"
            ]
          }
        }
      ],
      "review_notes": [
        "A10 postconditions are checked via the after_step snapshot of the final dressing state."
      ]
    },
    {
      "action_id": "A11",
      "preconditions": [],
      "postconditions": [
        {
          "requirement_id": "A11_post_1",
          "condition": "The user has notified the nurse following the detection of infection signs or fever.",
          "source": "explicit_instruction",
          "source_reference": "Call your nurse if the burn becomes more red or swollen, starts to smell or leak pus, or if you develop a fever.",
          "requires_expert_review": true,
          "evidence_specification": {
            "evidence_types": [
              "human_confirmation"
            ],
            "relevant_entities": [
              "nurse",
              "user"
            ],
            "observable_cues": [
              "Confirmation that a call or notification was placed"
            ],
            "temporal_scope": "after_action",
            "verification_method": "human_confirmation",
            "observability": "not_observable",
            "current_support": "human_required",
            "limitations": [
              "fever and odor cannot be detected by RGB",
              "increased redness or swelling requires comparison with baseline which is not currently supported",
              "the act of calling is not captured in burn site snapshots"
            ]
          }
        }
      ],
      "error_criteria": [],
      "review_notes": [
        "Action A11 is conditional and relies on clinical assessments (fever, smell, redness) and communication events outside the current camera's scope. It requires human confirmation."
      ]
    }
  ],
  "procedure_error_criteria": [],
  "review_notes": [
    "Verification of tape placement (A10) is limited by occlusion once the gauze is applied.",
    "Notification (A11) is clinical and communication-based, necessitating expert or human verification as RGB snapshots of the burn site provide insufficient evidence for fever, smell, or the act of calling."
  ]
}
